const on = Object.values(eng.state.layers).filter((l) => l && l.on).length;
if (pts) parts.push(`Точек <b>${formatInt(pts)}</b>`);
parts.push(`Эффектов включено <b>${on}</b>`);
el.innerHTML = parts.map((p) => `<span>${p}</span>`).join('');
